function Epoch-Now{[DateTimeOffset]::UtcNow.ToUnixTimeSeconds()}
function Iso-Now{[DateTime]::UtcNow.ToString('o')}
function Sha([string]$Path){if(-not(Test-Path -LiteralPath $Path)){return $null};(Get-FileHash -Algorithm SHA256 -LiteralPath $Path).Hash.ToLowerInvariant()}
function N($Value,[double]$Default=0){$parsed=0.0;if($null -ne $Value -and [double]::TryParse([string]$Value,[Globalization.NumberStyles]::Float,[Globalization.CultureInfo]::InvariantCulture,[ref]$parsed)){return $parsed};$Default}
function B($Value){$s=[string]$Value;return $Value -eq $true -or $Value -eq 1 -or $s.ToLowerInvariant() -eq 'true'}
function Csv-Pair([string]$Path){if(-not(Test-Path -LiteralPath $Path)){return $null};$lines=@(Get-Content -LiteralPath $Path -TotalCount 2);if($lines.Count -ne 2){return $null};$lines|ConvertFrom-Csv|Select-Object -First 1}
function Atomic-Text([string]$Path,[string]$Text){$dir=Split-Path -Parent $Path;New-Item -ItemType Directory -Force -Path $dir|Out-Null;$tmp="$Path.tmp";[IO.File]::WriteAllText($tmp,$Text,(New-Object Text.UTF8Encoding($false)));Move-Item -Force -LiteralPath $tmp -Destination $Path}
function Atomic-Json([string]$Path,$Value){Atomic-Text $Path (($Value|ConvertTo-Json -Depth 30)+"`n")}
function Import-TreeCsv([string]$Path){$rows=@();if(Test-Path -LiteralPath $Path){foreach($file in @(Get-ChildItem -LiteralPath $Path -Filter '*.csv' -File -Recurse|Sort-Object FullName)){try{$rows+=@(Import-Csv -LiteralPath $file.FullName)}catch{}}};@($rows)}
function Detail-Map([string]$Text){$map=@{};foreach($part in @($Text -split ';')){if($part -match '='){$bits=$part -split '=',2;$map[$bits[0]]=$bits[1]}};$map}
function Median($Values){$a=@($Values|ForEach-Object{N $_}|Sort-Object);if($a.Count -eq 0){return $null};$m=[int]($a.Count/2);if($a.Count%2){return [double]$a[$m]};return ([double]$a[$m-1]+[double]$a[$m])/2.0}
function Max-Drawdown($Rows,[string]$Key){$equity=0.0;$peak=0.0;$worst=0.0;foreach($row in @($Rows|Sort-Object {[long](N $_.entry_utc)})){$equity+=N $row.$Key;if($equity -gt $peak){$peak=$equity};$dd=$peak-$equity;if($dd -gt $worst){$worst=$dd}};$worst}
function Concentration($Rows,[string]$GroupKey,[string]$PayoffKey){
 if(@($Rows).Count -eq 0){return [ordered]@{dominant='';entry_fraction=$null;absolute_net_r_fraction=$null}}
 $groups=@($Rows|Group-Object -Property $GroupKey);$dominant=$groups|Sort-Object Count,Name -Descending|Select-Object -First 1;$contrib=@();foreach($g in $groups){$sum=($g.Group|Measure-Object -Property $PayoffKey -Sum).Sum;$contrib+=[pscustomobject]@{name=$g.Name;net=[double](N $sum);absolute=[Math]::Abs([double](N $sum))}}
 $largest=$contrib|Sort-Object absolute,name -Descending|Select-Object -First 1;$totalAbs=($contrib|Measure-Object -Property absolute -Sum).Sum
 [ordered]@{dominant=$dominant.Name;entry_fraction=$dominant.Count/@($Rows).Count;largest_absolute_net_r_contributor=$largest.name;absolute_net_r_fraction=if((N $totalAbs)-gt 0){$largest.absolute/(N $totalAbs)}else{$null}}
}
function Payoff-Metrics($Rows,[string]$Key){
 $ordered=@($Rows|Sort-Object {[long](N $_.entry_utc)});$pays=@($ordered|ForEach-Object{N $_.$Key});$wins=@($pays|Where-Object{$_ -gt 0});$losses=@($pays|Where-Object{$_ -lt 0});$total=($pays|Measure-Object -Sum).Sum;if($null -eq $total){$total=0.0};$grossWin=($wins|Measure-Object -Sum).Sum;if($null -eq $grossWin){$grossWin=0.0};$grossLoss=-1*(N (($losses|Measure-Object -Sum).Sum));$avgWin=if($wins.Count){(N $grossWin)/$wins.Count}else{$null};$avgLoss=if($losses.Count){-1*$grossLoss/$losses.Count}else{$null}
 $day=@{};foreach($row in $ordered){$d=[DateTimeOffset]::FromUnixTimeSeconds([long](N $row.entry_utc)).UtcDateTime.ToString('yyyy-MM-dd');if(-not $day.ContainsKey($d)){$day[$d]=0.0};$day[$d]+=N $row.$Key};$bestDay='';$bestDayNet=0.0;if($day.Count){$bestDay=($day.GetEnumerator()|Sort-Object Value,Name -Descending|Select-Object -First 1).Key;$bestDayNet=$day[$bestDay]};$best=if($wins.Count){($wins|Measure-Object -Maximum).Maximum}else{0.0}
 [ordered]@{trades=$ordered.Count;total_net_r=[double]$total;expectancy_r=if($ordered.Count){(N $total)/$ordered.Count}else{$null};max_drawdown_r=Max-Drawdown $ordered $Key;profit_factor=if($grossLoss -gt 0){(N $grossWin)/$grossLoss}else{$null};average_winner_r=$avgWin;average_loser_r=$avgLoss;payoff_ratio=if($null -ne $avgWin -and $null -ne $avgLoss -and $avgLoss -ne 0){$avgWin/[Math]::Abs($avgLoss)}else{$null};result_without_best_winner_r=(N $total)-(N $best);best_day_utc=$bestDay;result_without_best_day_r=(N $total)-(N $bestDayNet);daily_net_r=$day}
}
function Candidate-Summary($Rows,[string]$CandidateId,[string]$SequenceId,[string]$Status){
 $selected=@($Rows|Where-Object{$_.candidate_id -eq $CandidateId -and $_.sequence_status -eq 'CLEAN'});$baselineLosses=@($selected|Where-Object{(N $_.baseline_final_r)-lt 0});$candidateLosses=@($selected|Where-Object{(N $_.candidate_final_r)-lt 0});$full=@($selected|Where-Object{$_.terminal_reason -eq 'INITIAL_STRUCTURAL_STOP'});$avoided=@($full|Where-Object{(B $_.candidate_fired) -and (N $_.candidate_final_r)-gt (N $_.baseline_final_r)});$base=Payoff-Metrics $selected 'baseline_final_r';$causal=Payoff-Metrics $selected 'candidate_final_r';$saved=($selected|ForEach-Object{(N $_.candidate_final_r)-(N $_.baseline_final_r)}|Measure-Object -Sum).Sum;if($null -eq $saved){$saved=0.0};$sym=Concentration $selected 'symbol' 'candidate_final_r';$ses=Concentration $selected 'session' 'candidate_final_r'
 [pscustomobject][ordered]@{schema='SOLTRADE_V3_INVALIDATION_ROLLING_V1';sequence_id=$SequenceId;sequence_status=$Status;model_id=$ModelId;candidate_id=$CandidateId;eligible_triggered_positions=$selected.Count;invalidations=@($selected|Where-Object{B $_.candidate_fired}).Count;full_minus_1_losses_avoided=$avoided.Count;full_minus_1_losses_not_avoided=$full.Count-$avoided.Count;average_losing_r_baseline=if($baselineLosses.Count){(N (($baselineLosses|Measure-Object -Property baseline_final_r -Average).Average))}else{$null};average_losing_r_with_invalidation=if($candidateLosses.Count){(N (($candidateLosses|Measure-Object -Property candidate_final_r -Average).Average))}else{$null};median_losing_r_baseline=Median @($baselineLosses|ForEach-Object{$_.baseline_final_r});median_losing_r_with_invalidation=Median @($candidateLosses|ForEach-Object{$_.candidate_final_r});total_r_saved_vs_baseline=[double](N $saved);interrupted_breakeven_recoveries=@($selected|Where-Object{(B $_.candidate_fired)-and(B $_.recovered_to_breakeven)}).Count;interrupted_bank1_trades=@($selected|Where-Object{(B $_.candidate_fired)-and(B $_.reached_plus_1_after_exit)}).Count;interrupted_plus_2_trades=@($selected|Where-Object{(B $_.candidate_fired)-and(B $_.reached_plus_2_after_exit)}).Count;interrupted_plus_3_trades=@($selected|Where-Object{(B $_.candidate_fired)-and(B $_.reached_plus_3_after_exit)}).Count;interrupted_plus_5_trades=@($selected|Where-Object{(B $_.candidate_fired)-and(B $_.reached_plus_5_after_exit)}).Count;baseline_total_net_r=$base.total_net_r;invalidation_total_net_r=$causal.total_net_r;expectancy_difference_r=if($selected.Count){(N $saved)/$selected.Count}else{$null};max_drawdown_baseline_r=$base.max_drawdown_r;max_drawdown_invalidation_r=$causal.max_drawdown_r;max_drawdown_difference_r=(N $base.max_drawdown_r)-(N $causal.max_drawdown_r);profit_factor=$causal.profit_factor;average_winner_r=$causal.average_winner_r;average_loser_r=$causal.average_loser_r;payoff_ratio=$causal.payoff_ratio;result_without_best_winner_r=$causal.result_without_best_winner_r;result_without_best_day_r=$causal.result_without_best_day_r;dominant_symbol=$sym.dominant;symbol_entry_fraction=$sym.entry_fraction;symbol_absolute_net_r_fraction=$sym.absolute_net_r_fraction;dominant_session=$ses.dominant;session_entry_fraction=$ses.entry_fraction;session_absolute_net_r_fraction=$ses.absolute_net_r_fraction}
}
function Write-Csv([string]$Path,$Rows,[string[]]$Fields){$dir=Split-Path -Parent $Path;New-Item -ItemType Directory -Force -Path $dir|Out-Null;$tmp="$Path.tmp";if(@($Rows).Count){@($Rows)|Select-Object -Property $Fields|Export-Csv -LiteralPath $tmp -NoTypeInformation -Encoding UTF8}else{[IO.File]::WriteAllText($tmp,($Fields -join ',')+"`r`n",(New-Object Text.UTF8Encoding($false)))};Move-Item -Force -LiteralPath $tmp -Destination $Path}

