 $checks=New-Object Collections.Generic.List[object];$errors=New-Object Collections.Generic.List[string]
 function Add([string]$Name,[bool]$Passed,$ExpectedValue,$ActualValue){$checks.Add([pscustomobject][ordered]@{name=$Name;passed=$Passed;expected=$ExpectedValue;actual=$ActualValue});if(-not $Passed){$errors.Add("$Name expected=$ExpectedValue actual=$ActualValue")}}
 $trackerSource=Join-Path $TrackerHome 'MQL5\Experts\SolTradeFullLifetimeTrackerV1.mq5';$trackerBinary=$trackerSource.Replace('.mq5','.ex5');$trackerModel=Join-Path $TrackerHome 'MQL5\Experts\SolTradeV3TrackingModel.mqh';$trackerData=Join-Path $TrackerHome 'MQL5\Files\SolTradeFullLifetimeTrackerV1';$candidate=Join-Path $trackerData 'frozen-invalidation-candidates.csv';$manifest=Csv-Pair (Join-Path $trackerData 'manifest.csv');$heartbeat=Csv-Pair (Join-Path $trackerData 'status\heartbeat.csv')
