 Add 'frozen_model_json_sha256' ((Sha (Join-Path $EvaluatorHome 'frozen-tracking-model.json'))-eq $Expected.frozen_model_json_sha256) $Expected.frozen_model_json_sha256 (Sha (Join-Path $EvaluatorHome 'frozen-tracking-model.json'))
 Add 'candidate_receipt_sha256' ((Sha $candidate)-eq $Expected.candidate_receipt_sha256) $Expected.candidate_receipt_sha256 (Sha $candidate)
 Add 'tracker_heartbeat_present' ($null-ne $heartbeat) 'present' $(if($null-ne $heartbeat){'present'}else{'missing'})
 if($null-ne $heartbeat){Add 'tracker_model_id' ($heartbeat.model_id-eq $Expected.model_id) $Expected.model_id $heartbeat.model_id;Add 'tracker_version' ($heartbeat.tracker_version-eq $Expected.tracker_version) $Expected.tracker_version $heartbeat.tracker_version;Add 'tracker_order_capability' ($heartbeat.order_capability-eq 'false') 'false' $heartbeat.order_capability;Add 'tracker_terminal_trade_allowed' ($heartbeat.terminal_trade_allowed-eq 'false') 'false' $heartbeat.terminal_trade_allowed;Add 'tracker_mql_trade_allowed' ($heartbeat.mql_trade_allowed-eq 'false') 'false' $heartbeat.mql_trade_allowed;Add 'tracker_position_time_limit' ($heartbeat.position_time_limit-eq 'none') 'none' $heartbeat.position_time_limit}
 Add 'tracker_manifest_present' ($null-ne $manifest) 'present' $(if($null-ne $manifest){'present'}else{'missing'})
 if($null-ne $manifest){Add 'manifest_entry_specification' ($manifest.entry_specification-eq 'FROZEN_V3_72_FEATURES_8_INTERACTIONS_THRESHOLDS') 'FROZEN_V3_72_FEATURES_8_INTERACTIONS_THRESHOLDS' $manifest.entry_specification;Add 'manifest_safety_disposition' ($manifest.safety_horizon_disposition-eq 'RIGHT_CENSORED') 'RIGHT_CENSORED' $manifest.safety_horizon_disposition;Add 'manifest_bank_action' ($manifest.bank_action-eq 'PLUS_1R_BANK_50_PERCENT_ONCE') 'PLUS_1R_BANK_50_PERCENT_ONCE' $manifest.bank_action;Add 'manifest_ratchet_deployed' ($manifest.ratchet_deployed-eq 'false') 'false' $manifest.ratchet_deployed}
 $sourceText=if(Test-Path $trackerSource){[IO.File]::ReadAllText($trackerSource)}else{''};$patterns=@('#include\s*<Trade/','\bCTrade\b',('\bOrder'+'Send(?:Async)?\s*\('),'\bMqlTradeRequest\b','\bTRADE_ACTION_','\bPositionClose\s*\(','\bPositionModify\s*\(','\bOrderDelete\s*\(');$hits=@();foreach($pattern in $patterns){if($sourceText-match $pattern){$hits+=$pattern}};Add 'tracker_trade_api_scan' ($hits.Count-eq 0) 'no trade APIs' ($hits-join ';')
 $fpSource='C:\SolTrade\MT5-FP-DEMO\MQL5\Experts\SolTrade\SolTradeFastMultiMarketV2.mq5';$fpBinary=$fpSource.Replace('.mq5','.ex5');Add 'fp_source_sha256' ((Sha $fpSource)-eq $Expected.fp_source_sha256) $Expected.fp_source_sha256 (Sha $fpSource);Add 'fp_binary_sha256' ((Sha $fpBinary)-eq $Expected.fp_binary_sha256) $Expected.fp_binary_sha256 (Sha $fpBinary)
 foreach($fx in @(@('fxify_10k','C:\SolTrade\state\fxify-10k.ini',$Expected.fxify_10k_startup_sha256),@('fxify_100k','C:\SolTrade\state\fxify-100k.ini',$Expected.fxify_100k_startup_sha256))){$text=if(Test-Path $fx[1]){[IO.File]::ReadAllText($fx[1])}else{''};Add "$($fx[0])_startup_sha256" ((Sha $fx[1])-eq $fx[2]) $fx[2] (Sha $fx[1]);Add "$($fx[0])_enabled_zero" ($text-match '(?m)^Enabled=0\r?$') 'Enabled=0' $(if($text-match '(?m)^Enabled=0\r?$'){'Enabled=0'}else{'missing'});Add "$($fx[0])_allow_live_zero" ($text-match '(?m)^AllowLiveTrading=0\r?$') 'AllowLiveTrading=0' $(if($text-match '(?m)^AllowLiveTrading=0\r?$'){'AllowLiveTrading=0'}else{'missing'})}
 $collector='C:\SolTrade\Research\SolTrade-Brain-Collector-V1';$collectorSource=Join-Path $collector 'MQL5\Experts\SolTradeBrainCollectorV1.mq5';$collectorBinary=$collectorSource.Replace('.mq5','.ex5');$collectorHb=Csv-Pair (Join-Path $collector 'MQL5\Files\SolTradeBrainCollectorV1\status\heartbeat.csv');Add 'collector_source_sha256' ((Sha $collectorSource)-eq $Expected.collector_source_sha256) $Expected.collector_source_sha256 (Sha $collectorSource);Add 'collector_binary_sha256' ((Sha $collectorBinary)-eq $Expected.collector_binary_sha256) $Expected.collector_binary_sha256 (Sha $collectorBinary);Add 'collector_heartbeat_present' ($null-ne $collectorHb) 'present' $(if($null-ne $collectorHb){'present'}else{'missing'});if($null-ne $collectorHb){Add 'collector_order_capability' ($collectorHb.order_capability-eq 'false') 'false' $collectorHb.order_capability;Add 'collector_terminal_trade_allowed' ($collectorHb.terminal_trade_allowed-eq 'false') 'false' $collectorHb.terminal_trade_allowed;Add 'collector_mql_trade_allowed' ($collectorHb.mql_trade_allowed-eq 'false') 'false' $collectorHb.mql_trade_allowed}
 $badCensored=@($Outcomes|Where-Object{$_.outcome_status-eq 'RIGHT_CENSORED' -and ((B $_.baseline_final_r_known)-or(B $_.aftermath_complete)-or -not[string]::IsNullOrWhiteSpace([string]$_.baseline_final_r))});Add 'right_censored_known_result_violations' ($badCensored.Count-eq 0) 0 $badCensored.Count
 $badOutcome=@($Outcomes|Where-Object{$_.order_capability -ne 'false' -or $_.completed_bars_only -ne 'true'});Add 'outcome_orderless_completed_bar_flags' ($badOutcome.Count -eq 0) 0 $badOutcome.Count
