}

function Build-PerTrade($Outcomes,$Events,$Observations,$Expected,[string]$Status){
 $terminal=@($Outcomes|Where-Object{$_.outcome_status-eq 'TERMINAL' -and $_.baseline_final_r_known-eq 'true' -and $_.aftermath_complete-eq 'true'});$unique=@();foreach($g in @($terminal|Group-Object {"$($_.opportunity_id)|$($_.candidate_id)"})){$unique+=@($g.Group|Sort-Object {[long](N $_.terminal_utc)}|Select-Object -Last 1)};$rows=@()
 foreach($outcome in @($unique|Sort-Object {[long](N $_.entry_utc)},candidate_id)){
  $opp=[string]$outcome.opportunity_id;$candidate=[string]$outcome.candidate_id;$entry=@($Events|Where-Object{$_.opportunity_id-eq $opp -and $_.event-eq 'ENTRY_TRIGGERED'}|Sort-Object {[long](N $_.utc_msc)}|Select-Object -First 1);$invalid=@($Events|Where-Object{$_.opportunity_id-eq $opp -and $_.event-eq 'CAUSAL_INVALIDATION' -and $_.candidate_id-eq $candidate}|Sort-Object {[long](N $_.utc_msc)}|Select-Object -First 1);$entryMap=if($entry.Count){Detail-Map $entry[0].detail}else{@{}};$invObs=$null;if($invalid.Count){$invObs=@($Observations|Where-Object{$_.opportunity_id-eq $opp -and [long](N $_.observation_utc_msc)-eq [long](N $invalid[0].utc_msc)}|Select-Object -Last 1)}
  $evidence='';if($invObs -and @($invObs).Count){$o=$invObs[0];$evidence="pressure_reversal=$($o.pressure_reversal);pullback_expanding=$($o.pullback_expanding);resumption_evidence=$($o.resumption_evidence);m1_state=$($o.m1_state);m5_state=$($o.m5_state);transition_score=$($o.transition_score)"}elseif($invalid.Count){$evidence="event_detail=$($invalid[0].detail);transition_score=$($invalid[0].transition_score)"}
  $base=N $outcome.baseline_final_r;$causal=N $outcome.causal_final_r;$ev=if($entryMap.ContainsKey('expected_net_r')){N $entryMap['expected_net_r']}else{$null};$quality=if($null-ne $ev){1.0/(1.0+[Math]::Exp(-2.0*$ev))}else{$null};$fire=B $outcome.causal_exit_triggered
  $rows+=[pscustomobject][ordered]@{schema='SOLTRADE_V3_PER_TRADE_FORWARD_EVIDENCE_V1';sequence_id=$Expected.sequence_id;sequence_status=$Status;model_id=$Expected.model_id;opportunity_id=$opp;symbol=$outcome.symbol;session=$outcome.session;direction=$outcome.direction;entry_utc=[long](N $outcome.entry_utc);terminal_utc=[long](N $outcome.terminal_utc);lifetime_seconds=[long](N $outcome.lifetime_seconds);initial_r_distance=N $outcome.initial_risk;baseline_final_r=$base;baseline_mfe_r=N $outcome.mfe_r;baseline_mae_r=N $outcome.mae_r;bank1_reached=B $outcome.bank1_reached;baseline_plus_2=((N $outcome.mfe_r)-ge 2);baseline_plus_3=((N $outcome.mfe_r)-ge 3);baseline_plus_5=((N $outcome.mfe_r)-ge 5);structural_stop_utc=[long](N $outcome.terminal_utc);runner_stop_utc=if($outcome.terminal_reason-eq 'RUNNER_STRUCTURAL_STOP'){[long](N $outcome.terminal_utc)}else{''};terminal_reason=$outcome.terminal_reason;entry_expected_net_r=$ev;entry_quality=$quality;entry_full_loss_probability=if($entryMap.ContainsKey('full_loss_probability')){N $entryMap['full_loss_probability']}else{$null};entry_bank1_probability=if($entryMap.ContainsKey('bank1_probability')){N $entryMap['bank1_probability']}else{$null};candidate_id=$candidate;candidate_fired=$fire;candidate_fire_utc=if($fire){[long](N $outcome.causal_exit_utc)}else{''};invalidation_r=if($fire){N $outcome.causal_exit_r}else{$null};invalidation_transition_score=if($invalid.Count){N $invalid[0].transition_score}else{$null};causal_evidence_state=$evidence;candidate_final_r=$causal;baseline_eventual_final_r=$base;recovered_to_breakeven=B $outcome.recovered_to_breakeven;reached_plus_1_after_exit=B $outcome.reached_bank1_after_exit;reached_plus_2_after_exit=B $outcome.reached_plus_2_after_exit;reached_plus_3_after_exit=B $outcome.reached_plus_3_after_exit;reached_plus_5_after_exit=B $outcome.reached_plus_5_after_exit;r_saved_vs_baseline=[Math]::Max(0,$causal-$base);r_lost_vs_baseline_if_interrupted=[Math]::Max(0,$base-$causal)}
 }
 @($rows)
}

function Entry-Summary($Rows,$Events,$Expected){
 $base=@($Rows|Where-Object{$_.candidate_id-eq $CandidateIds[0]}|Sort-Object entry_utc);$detected=@($Events|Where-Object{$_.event-eq 'OPPORTUNITY_DETECTED'}|Group-Object opportunity_id);$entered=@($Events|Where-Object{$_.event-eq 'ENTRY_TRIGGERED'}|Group-Object opportunity_id);$abandoned=@($Events|Where-Object{$_.event-eq 'OPPORTUNITY_ABANDONED'}|Group-Object opportunity_id);$metrics=Payoff-Metrics $base 'baseline_final_r';$calibration=@()
 foreach($band in @($Expected.quality_bands)){$low=N $band[0];$high=N $band[1];$group=@($base|Where-Object{$null-ne $_.entry_quality -and (N $_.entry_quality)-ge $low -and (N $_.entry_quality)-lt $high});if($group.Count){$calibration+=[pscustomobject][ordered]@{quality_low=$low;quality_high=$high;completed_entries=$group.Count;average_net_r=(N (($group|Measure-Object -Property baseline_final_r -Average).Average));full_loss_rate=@($group|Where-Object{$_.terminal_reason-eq 'INITIAL_STRUCTURAL_STOP'}).Count/$group.Count;bank1_rate=@($group|Where-Object{B $_.bank1_reached}).Count/$group.Count;plus_2_rate=@($group|Where-Object{B $_.baseline_plus_2}).Count/$group.Count;plus_3_rate=@($group|Where-Object{B $_.baseline_plus_3}).Count/$group.Count;plus_5_rate=@($group|Where-Object{B $_.baseline_plus_5}).Count/$group.Count}}}
 [ordered]@{schema='SOLTRADE_V3_ENTRY_FORWARD_SUMMARY_V1';sequence_id=$Expected.sequence_id;sequence_status='CLEAN';model_id=$Expected.model_id;generated_utc=Iso-Now;opportunities_detected=$detected.Count;wait_state_count=$detected.Count;wait_definition='Every OPPORTUNITY_DETECTED enters WAIT_FOR_TRANSITION before ENTER or ABANDON';enter_count=$entered.Count;abandon_count=$abandoned.Count;currently_unresolved_opportunities=[Math]::Max(0,$detected.Count-$entered.Count-$abandoned.Count);long_count=@($entered|Where-Object{$_.Group[0].direction-eq 'LONG'}).Count;short_count=@($entered|Where-Object{$_.Group[0].direction-eq 'SHORT'}).Count;known_completed_positions=$base.Count;right_censored_positions=@($Events|Where-Object{$_.event-eq 'RIGHT_CENSORED'}|Group-Object opportunity_id).Count;full_losses=@($base|Where-Object{$_.terminal_reason-eq 'INITIAL_STRUCTURAL_STOP'}).Count;full_loss_rate=if($base.Count){@($base|Where-Object{$_.terminal_reason-eq 'INITIAL_STRUCTURAL_STOP'}).Count/$base.Count}else{$null};bank1_count=@($base|Where-Object{B $_.bank1_reached}).Count;bank1_rate=if($base.Count){@($base|Where-Object{B $_.bank1_reached}).Count/$base.Count}else{$null};plus_2_count=@($base|Where-Object{B $_.baseline_plus_2}).Count;plus_2_rate=if($base.Count){@($base|Where-Object{B $_.baseline_plus_2}).Count/$base.Count}else{$null};plus_3_count=@($base|Where-Object{B $_.baseline_plus_3}).Count;plus_3_rate=if($base.Count){@($base|Where-Object{B $_.baseline_plus_3}).Count/$base.Count}else{$null};plus_5_count=@($base|Where-Object{B $_.baseline_plus_5}).Count;plus_5_rate=if($base.Count){@($base|Where-Object{B $_.baseline_plus_5}).Count/$base.Count}else{$null};net_r=$metrics.total_net_r;expectancy_r=$metrics.expectancy_r;max_drawdown_r=$metrics.max_drawdown_r;result_without_best_winner_r=$metrics.result_without_best_winner_r;result_without_best_day_r=$metrics.result_without_best_day_r;quality_definition='1/(1+exp(-2*entry_expected_net_r))';quality_calibration_bands=$calibration;development_search_rerun=$false;tuning_enabled=$false;promotion_authorized=$false}
}

function Self-Test{
 $r=@(
  [pscustomobject]@{sequence_status='CLEAN';candidate_id='FROZEN_V3_DIAGNOSTIC';candidate_fired=$true;baseline_final_r=-1.0;candidate_final_r=-0.4;entry_utc=1000;terminal_reason='INITIAL_STRUCTURAL_STOP';symbol='EURUSD.r';session='LONDON';recovered_to_breakeven=$false;reached_plus_1_after_exit=$false;reached_plus_2_after_exit=$false;reached_plus_3_after_exit=$false;reached_plus_5_after_exit=$false},
  [pscustomobject]@{sequence_status='CLEAN';candidate_id='FROZEN_V3_DIAGNOSTIC';candidate_fired=$true;baseline_final_r=3.0;candidate_final_r=-0.4;entry_utc=2000;terminal_reason='RUNNER_STRUCTURAL_STOP';symbol='XAUUSD.r';session='NEW_YORK';recovered_to_breakeven=$true;reached_plus_1_after_exit=$true;reached_plus_2_after_exit=$true;reached_plus_3_after_exit=$true;reached_plus_5_after_exit=$false}
 );$s=Candidate-Summary $r 'FROZEN_V3_DIAGNOSTIC' 'SELF_TEST' 'CLEAN';if($s.eligible_triggered_positions-ne 2){throw 'self-test eligible count'};if($s.full_minus_1_losses_avoided-ne 1){throw 'self-test loss avoided'};if([Math]::Abs((N $s.total_r_saved_vs_baseline)-(-2.8))-gt 1e-9){throw 'self-test total delta'};if($s.interrupted_plus_3_trades-ne 1){throw 'self-test interrupted tail'};[ordered]@{schema='SOLTRADE_V3_FORWARD_EVALUATOR_SELF_TEST_V1';status='PASS';tests=4;order_capability=$false}|ConvertTo-Json -Depth 5
}

if($SelfTest){Self-Test;exit 0}
if([string]::IsNullOrWhiteSpace($ExpectedIdentityPath)){$ExpectedIdentityPath=Join-Path $EvaluatorHome 'expected-identities.json'}
$output=Join-Path $EvaluatorHome 'output';$stateDir=Join-Path $EvaluatorHome 'state';$statusDir=Join-Path $EvaluatorHome 'status';New-Item -ItemType Directory -Force -Path $output,$stateDir,$statusDir,(Join-Path $output 'daily')|Out-Null
$lockPath=Join-Path $stateDir 'evaluator.lock';$lock=$null
try{$lock=[IO.File]::Open($lockPath,[IO.FileMode]::OpenOrCreate,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None)}catch{exit 0}
try{
 $Expected=Get-Content -Raw -LiteralPath $ExpectedIdentityPath|ConvertFrom-Json;$trackerData=Join-Path $TrackerHome 'MQL5\Files\SolTradeFullLifetimeTrackerV1';$outcomes=@(Import-TreeCsv (Join-Path $trackerData 'outcomes')|Where-Object{$_.PSObject.Properties.Name -contains 'outcome_status'});$events=@(Import-TreeCsv (Join-Path $trackerData 'events')|Where-Object{$_.PSObject.Properties.Name -contains 'event'});$observations=@(Import-TreeCsv (Join-Path $trackerData 'lifetime_observations')|Where-Object{$_.PSObject.Properties.Name -contains 'observation_utc_msc'});$integrity=Integrity-Check -Expected $Expected -Outcomes $outcomes -Events $events -Observations $observations
 $sequencePath=Join-Path $stateDir 'sequence.json';$sequence=$null;if(Test-Path $sequencePath){try{$sequence=Get-Content -Raw -LiteralPath $sequencePath|ConvertFrom-Json}catch{$sequence=$null}};if($null-eq $sequence){$sequence=[pscustomobject][ordered]@{schema='SOLTRADE_V3_FORWARD_SEQUENCE_V1';sequence_id=$Expected.sequence_id;started_utc=Iso-Now;status='CLEAN';contamination_detected_utc=$null;contamination_reasons=@();last_run_utc=$null}}
 $reasons=New-Object Collections.Generic.List[string];foreach($x in @($sequence.contamination_reasons)){$reasons.Add([string]$x)};if($sequence.sequence_id-ne $Expected.sequence_id){$reasons.Add("sequence_id expected=$($Expected.sequence_id) actual=$($sequence.sequence_id)")};foreach($x in @($integrity.errors)){$reasons.Add([string]$x)};$distinct=@($reasons|Select-Object -Unique);if($sequence.status-eq 'EVIDENCE_CONTAMINATED' -or $distinct.Count){$sequence.status='EVIDENCE_CONTAMINATED';if($null-eq $sequence.contamination_detected_utc){$sequence.contamination_detected_utc=Iso-Now};$sequence.contamination_reasons=$distinct;$integrity.status='EVIDENCE_CONTAMINATED';$integrity.errors=$distinct}else{$sequence.status='CLEAN'};$sequence.last_run_utc=Iso-Now;Atomic-Json $sequencePath $sequence;Atomic-Json (Join-Path $output 'integrity-receipt.json') $integrity
 if($sequence.status-eq 'EVIDENCE_CONTAMINATED'){$heartbeat=[ordered]@{schema='SOLTRADE_V3_FORWARD_EVALUATOR_HEARTBEAT_V1';status='EVIDENCE_CONTAMINATED';sequence_id=$Expected.sequence_id;utc=Epoch-Now;completed_positions_evaluated=0;integrity_errors=$distinct;order_capability=$false;deployment_capability=$false};Atomic-Json (Join-Path $statusDir 'heartbeat.json') $heartbeat;$snap=[ordered]@{schema='SOLTRADE_V3_FORWARD_DAILY_SNAPSHOT_V1';status='EVIDENCE_CONTAMINATED';generated_utc=Iso-Now;sequence=$sequence;integrity=$integrity;results_included=$false};Atomic-Json (Join-Path (Join-Path $output 'daily') ((Get-Date).ToUniversalTime().ToString('yyyyMMdd')+'-snapshot.json')) $snap;exit 2}
 $perTrade=Build-PerTrade $outcomes $events $observations $Expected 'CLEAN';Write-Csv (Join-Path $output 'per-trade-evidence.csv') $perTrade $PerTradeFields;$summaries=@();foreach($id in $CandidateIds){$summaries+=Candidate-Summary $perTrade $id $Expected.sequence_id 'CLEAN'};Write-Csv (Join-Path $output 'rolling-invalidation-summary.csv') $summaries $SummaryFields;$summaryPayload=[ordered]@{schema='SOLTRADE_V3_INVALIDATION_ROLLING_SET_V1';sequence_id=$Expected.sequence_id;sequence_status='CLEAN';model_id=$Expected.model_id;generated_utc=Iso-Now;candidate_selection_performed=$false;recommendation_emitted=$false;candidates=$summaries};Atomic-Json (Join-Path $output 'rolling-invalidation-summary.json') $summaryPayload;$entrySummary=Entry-Summary $perTrade $events $Expected;Atomic-Json (Join-Path $output 'rolling-v3-entry-summary.json') $entrySummary
 $completed=@($perTrade|Where-Object{$_.candidate_id-eq $CandidateIds[0]}).Count;$heartbeat=[ordered]@{schema='SOLTRADE_V3_FORWARD_EVALUATOR_HEARTBEAT_V1';status=if($completed){'EVALUATING_FORWARD_EVIDENCE'}else{'WAITING_FOR_FIRST_COMPLETED_HYPOTHETICAL_TRADE'};sequence_id=$Expected.sequence_id;utc=Epoch-Now;completed_positions_evaluated=$completed;candidate_rows=@($perTrade).Count;integrity_status='CLEAN';order_capability=$false;deployment_capability=$false;tuning_enabled=$false};Atomic-Json (Join-Path $statusDir 'heartbeat.json') $heartbeat;$snapshot=[ordered]@{schema='SOLTRADE_V3_FORWARD_DAILY_SNAPSHOT_V1';status=$heartbeat.status;generated_utc=Iso-Now;sequence=$sequence;integrity=$integrity;v3_entry_summary=$entrySummary;invalidation_summary=$summaryPayload;per_trade_rows=@($perTrade).Count};Atomic-Json (Join-Path (Join-Path $output 'daily') ((Get-Date).ToUniversalTime().ToString('yyyyMMdd')+'-snapshot.json')) $snapshot
}catch{$errorReceipt=[ordered]@{schema='SOLTRADE_V3_FORWARD_EVALUATOR_ERROR_V1';status='EVALUATOR_ERROR';utc=Iso-Now;message=$_.Exception.Message;order_capability=$false};Atomic-Json (Join-Path $statusDir 'heartbeat.json') $errorReceipt;throw}finally{if($null-ne $lock){$lock.Dispose()}}
